private void CarregarRelatorio(DataTable dtTransportes, DataTable dtInsumos)
{
    // Cria um DataSet e adiciona os dois DataTables
    DataSet ds = new DataSet();
    ds.Tables.Add(dtTransportes); // índice 0
    ds.Tables.Add(dtInsumos);     // índice 1

    // Limpa datasources existentes
    reportViewer1.LocalReport.DataSources.Clear();

    // Adiciona os dois DataSources com os mesmos nomes definidos no .rdlc
    reportViewer1.LocalReport.DataSources.Add(
        new ReportDataSource("dsTransportes", ds.Tables[0]));

    reportViewer1.LocalReport.DataSources.Add(
        new ReportDataSource("dsInsumos", ds.Tables[1]));

    // Carrega o arquivo RDLC
    reportViewer1.LocalReport.ReportPath = @"Relatorios\RelTransportesInsumos.rdlc";

    // Atualiza
    reportViewer1.RefreshReport();
}

